	/**
	 * Choosing a physical algorithm must not change the plan. {@code precompile} is expected to be a pure function of
	 * the tree and callers may invoke it more than once; before the stable-order decision moved into
	 * {@code optimize()}, {@code prepare(Distinct, ...)} reached into the already-optimized tree, swapped join
	 * arguments and set statement orders, which is why the plan logged as the "Optimized query model" was not the plan
	 * that ran.
	 * <p>
	 * The DISTINCT is over two variables, {@code ?a} and {@code ?parent}, either of which could supply a stable order,
	 * so this is exactly the shape that used to be rewritten. Either choice is correct:
	 * {@code LmdbPartitionedDistinctIteration} deduplicates the full {@code (a, parent)} tuple within each partition,
	 * so the partition variable does not have to be {@code ?a} for the extracted {@code ?a} values to come out
	 * distinct.
	 */
	@Test
	void testPrecompileDoesNotModifyTheOptimizedPlan() {
		EvaluationStrategy strategy = createStrategy();
		TupleExpr tupleExpr = parse("select distinct ?a ?parent where { ?type <urn:parent> ?parent. ?a a ?type. }");

		strategy.optimize(tupleExpr, new EvaluationStatistics(), EmptyBindingSet.getInstance());
		Distinct distinct = findNode(tupleExpr, Distinct.class);
		assertNotNull(distinct);

		String optimizedPlan = planStructure(tupleExpr);

		strategy.precompile(distinct);
		assertEquals(optimizedPlan, planStructure(tupleExpr), "preparation must not rewrite the optimized plan");

		QueryEvaluationStep prepared = strategy.precompile(distinct);
		assertEquals(optimizedPlan, planStructure(tupleExpr), "preparation must not rewrite the optimized plan");

		try (CloseableIteration<BindingSet> iteration = prepared.evaluate(EmptyBindingSet.getInstance())) {
			assertEquals(PARTITIONED_ITERATOR, iteration.getClass().getSimpleName());
			assertEquals(List.of("urn:s1", "urn:s2", "urn:s3", "urn:s4"), extractValues(iteration, "a"));
		}
	}

